def is_brackets_balanced(s: str) -> bool:
    stack = []  # Initialize an empty stack to keep track of opening brackets.
    mapping = {")": "(", "]": "[", "}": "{"}  # Define a mapping of closing to opening brackets.

    # Iterate through each character in the input string.
    for char in s:
        # Check if the current character is an opening bracket.
        if char in mapping.values():
            stack.append(char)  # If it's an opening bracket, push it onto the stack.
        # Check if the current character is a closing bracket.
        elif char in mapping:
            # If the stack is empty or the top of the stack doesn't match the corresponding opening bracket, it's unbalanced.
            if not stack or stack.pop() != mapping[char]:
                return False  # Mismatch found or stack is empty, so return False.

    # After iterating through all characters, if the stack is empty, all brackets were balanced.
    return not stack  # Return True if the stack is empty, indicating all brackets are matched.

