def is_sorted(numbers: list) -> bool:
    # An empty list is considered sorted.
    if not numbers:
        return True

    # A list with a single element is also considered sorted.
    if len(numbers) == 1:
        return True

    # Iterate through the list starting from the second element.
    for i in range(1, len(numbers)):
        # Compare the current element with the previous one.
        if numbers[i] < numbers[i-1]:
            # If an element is smaller than its predecessor, the list is not sorted.
            return False

    # If the loop completes, all elements were in ascending order.
    return True # All elements are in ascending order.

