def fibonacci_sequence(n: int) -> list[int]:
    # Initialize the Fibonacci sequence with the first two numbers
    sequence = [0, 1]

    # Handle edge cases where n is 0 or 1
    if n <= 0:
        return [] # Return an empty list for non-positive limits
    elif n == 1:
        return [0] # Return [0] when the limit is 1

    # Generate Fibonacci numbers until the last number is less than n
    while sequence[-1] < n:
        next_fib = sequence[-1] + sequence[-2] # Calculate the next Fibonacci number
        if next_fib < n:
            sequence.append(next_fib) # Add the new number if it's within the limit
        else:
            break # Stop if the next number exceeds or equals the limit

    # Return the generated sequence
    return sequence # The final list of Fibonacci numbers

