def generate_primes(n: int) -> list[int]:
    """
    Generates a list of prime numbers up to n (inclusive).
    Uses a simple trial division method.
    """
    primes = []  # Initialize an empty list to store prime numbers
    if n < 2:
        return primes  # No primes less than 2

    # Iterate through numbers from 2 up to n
    for num in range(2, n + 1):
        is_prime = True  # Assume the current number is prime
        # Check for divisibility from 2 up to the square root of num
        # This optimization reduces unnecessary checks
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False  # If divisible, it's not prime
                break  # No need to check further divisors
        if is_prime:
            primes.append(num)  # Add the number to the primes list if it's prime
    return primes  # Return the final list of prime numbers

