def convert_length(value, from_unit, to_unit):
    # Define the conversion factor from meters to feet
    METERS_TO_FEET_FACTOR = 3.28084

    # Check if the conversion is from meters to feet
    if from_unit == 'm' and to_unit == 'ft':
        return value * METERS_TO_FEET_FACTOR  # Perform the conversion

    # Check if the conversion is from feet to meters
    elif from_unit == 'ft' and to_unit == 'm':
        return value / METERS_TO_FEET_FACTOR  # Perform the inverse conversion

    # Check if the units are the same, no conversion needed
    elif from_unit == to_unit:
        return value

    # Handle invalid unit combinations
    else:
        # Raise a ValueError for unsupported unit types
        raise ValueError("Unsupported unit conversion. Use 'm' for meters or 'ft' for feet.")

