        self.balance += amount
        # Devuelve True para un depósito exitoso.
        return True

    def withdraw(self, amount):
        # Método para retirar fondos de la cuenta.
        if not isinstance(amount, (int, float)) or amount <= 0:
            # Los retiros deben ser números positivos.
            return False
        if self.balance < amount:
            # Comprueba si hay fondos suficientes antes del retiro.
            return False  # Fondos insuficientes.
        self.balance -= amount
        # Devuelve True para un retiro exitoso.
        return True

    def get_balance(self):
        # Un método auxiliar para recuperar el saldo actual de la cuenta.
        return self.balance

