def check_password_strength(password):
    # Initialize criteria flags
    has_upper = False
    has_lower = False
    has_digit = False

    # Iterate through characters to check for different types
    for char in password:
        if 'A' <= char <= 'Z':
            has_upper = True
        elif 'a' <= char <= 'z':
            has_lower = True
        elif '0' <= char <= '9':
            has_digit = True

    # Count how many of the three specific criteria are met
    met_criteria_count = sum([has_upper, has_lower, has_digit])

    # Check for 'Strong' password conditions
    if len(password) >= 8 and has_upper and has_lower and has_digit:
        return 'Strong'

    # Check for 'Medium' password conditions
    # This includes length and at least two out of three character types
    elif len(password) >= 6 and met_criteria_count >= 2:
        return 'Medium'

    # If neither 'Strong' nor 'Medium' conditions are met, it's 'Weak'
    else:
        return 'Weak'

